design_artifacts.class_diagram_mermaid:
```mermaid
classDiagram
    class Calculator {
        +evaluate(expression: str) -> str
        -parse(expression: str) -> list
        -compute(tokens: list) -> Decimal
        -format_result(value: Decimal) -> str
    }
    class Tokenizer {
        +tokenize(expression: str) -> list
        -is_operator(char: str) -> bool
        -is_digit(char: str) -> bool
    }
    class Parser {
        +parse(tokens: list) -> ASTNode
        -parse_expression() -> ASTNode
        -parse_term() -> ASTNode
        -parse_factor() -> ASTNode
    }
    class ASTNode {
        <<abstract>>
        +evaluate() -> Decimal
    }
    class NumberNode {
        -value: Decimal
        +evaluate() -> Decimal
    }
    class BinaryOpNode {
        -left: ASTNode
        -right: ASTNode
        -operator: str
        +evaluate() -> Decimal
    }
    class Formatter {
        +format(value: Decimal) -> str
    }
    class ErrorHandler {
        +handle_error(error: Exception) -> str
    }
    Calculator --> Tokenizer
    Calculator --> Parser
    Calculator --> Formatter
    Calculator --> ErrorHandler
    Parser --> ASTNode
    ASTNode <|-- NumberNode
    ASTNode <|-- BinaryOpNode
```

